import net, strutils, json, os, asyncdispatch, asynchttpserver, asyncnet, httpclient, uri, strformat, tables, times, random

var server = newAsyncHttpServer()

proc callCerebras(messages: JsonNode; maxTokens: int = 8192): Future[string] {.async.} =
  echo "[CEREBRAS] API hívás..."
  let client = newAsyncHttpClient()
  try:
    client.headers = newHttpHeaders({
      "Authorization": "Bearer " & getEnv("CEREBRAS_API_KEY"),
      "Content-Type": "application/json"
    })
    let bodyJson = %*{
      "model": "gpt-oss-120b",
      "messages": messages,
      "stream": false,
      "max_completion_tokens": maxTokens,
      "temperature": 0.1,
      "top_p": 0.95
    }
    let response = await client.postContent("", $bodyJson)
    let jsonResponse = parseJson(response)
    if jsonResponse.hasKey("choices") and jsonResponse["choices"].len > 0:
      let content = jsonResponse["choices"][0]["message"]["content"].getStr()
      echo fmt"[CEREBRAS] Válasz kapva: {content.len} karakter"
      return content
    else:
      return "Hiba: A Cerebras API nem adott vissza érvényes választ."
  except Exception as e:
    echo fmt"[CEREBRAS-HIBA] {e.msg}"
    return fmt"Cerebras API hiba: {e.msg}"
  finally:
    client.close()

proc exaSearch(query: string; numResults: int = 100; useAutoprompt: bool = true): Future[JsonNode] {.async.} =
  echo fmt"[EXA] Keresés indul: '{query}'"
  let client = newAsyncHttpClient()
  try:
    client.headers = newHttpHeaders({
      "x-api-key": getEnv("EXA_API_KEY"),
      "Content-Type": "application/json",
      "User-Agent": "JadedReplit/1.0"
    })
    var body: JsonNode
    if useAutoprompt:
      body = %*{"query": query, "numResults": numResults, "useAutoprompt": true}
    else:
      body = %*{"query": query, "numResults": numResults}

    let response = await client.postContent("", $body)
    let searchResponseId = (await client.postContent("", $body)).parseJson()["id"].getStr()

    await sleepAsync(2000)

    var results: JsonNode
    var attempts = 0
    while attempts < 10:
        let statusResponse = await client.get(fmt"")
        results = statusResponse.body.parseJson()
        if results["results"].len > 0:
            echo fmt"[EXA] Találatok megérkeztek: {results["results"].len} db"
            return results
        attempts += 1
        await sleepAsync(2000)

    return %*{"error": "Nem sikerült eredményeket lekérni az Exa-tól."}

  except Exception as e:
    echo fmt"[EXA-HIBA] {e.msg}"
    return %*{"error": fmt"Exa API hiba: {e.msg}"}
  finally:
    client.close()

proc performDeepResearch(userQuery: string): Future[JsonNode] {.async.} =
  var researchData = ""
  var sources = newTable

  echo "[RESEARCH] 1. fázis: Kezdeti mélykeresés"
  let initialSearch = await exaSearch(userQuery, numResults=100, useAutoprompt=true)
  if initialSearch.hasKey("results"):
    for result in initialSearch["results"]:
      if not sources.hasKey(result["url"].getStr()):
        sources[result["url"].getStr()] = result

  echo "[RESEARCH] 2. fázis: Dinamikus kulcsszó generálás"
  let keywordsPrompt = %*[
    {"role": "system", "content": "You are a research strategist. Based on the user's query, generate 5 diverse, highly relevant, and specific search keywords to build a comprehensive report. Return ONLY a JSON array of strings. Example: [\"keyword1\", \"keyword2\"]."},
    {"role": "user", "content": userQuery}
  ]
  let keywordsResponse = await callCerebras(keywordsPrompt, maxTokens=500)

  try:
    let keywords = parseJson(keywordsResponse)
    if keywords.kind == JArray:
      echo fmt"[RESEARCH] Generált kulcsszavak: {keywords}"
      for keywordNode in keywords:
        let keyword = keywordNode.getStr()
        echo fmt"[RESEARCH] Kiegészítő keresés: {keyword}"
        let additionalSearch = await exaSearch(keyword, numResults=50, useAutoprompt=false)
        if additionalSearch.hasKey("results"):
          for result in additionalSearch["results"]:
            if not sources.hasKey(result["url"].getStr()):
              sources[result["url"].getStr()] = result
  except JsonParsingError:
    echo "[RESEARCH-HIBA] Nem sikerült a kulcsszavakat JSON-ként feldolgozni."

  echo fmt"[RESEARCH] Összesen {sources.len} egyedi forrás gyűjtve."
  for url, result in sources:
    let title = result.getOrDefault("title").getStr("N/A")
    let text = result.getOrDefault("text").getStr("")
    researchData.add(fmt"Forrás: {title}\nURL: {url}\nTartalom:\n{text}\n\n---\n\n")

  echo "[RESEARCH] 3. fázis: Részletes jelentés generálása"
  let reportPrompt = %*[
    {"role": "system", "content": fmt"""Te egy világszínvonalú kutató elemző vagy. A felhasználó kérése: '{userQuery}'. Készíts egy rendkívül részletes, legalább 30,000 karakter hosszúságú, tudományos igényű jelentést magyarul. Használd a megadott forrásokat. A jelentés legyen tagolt, fejezetekkel, összefoglalóval és forrásjegyzékkel."""},
    {"role": "user", "content": fmt"Kutatási anyag:\n{researchData}"}
  ]

  let finalReport = await callCerebras(reportPrompt, maxTokens=8192)
  var sourceList: seq[JsonNode]
  for url, data in sources:
    sourceList.add(%*{"title": data.getOrDefault("title").getStr("N/A"), "url": url})

  return %*{"report": finalReport, "sources": newJArray(sourceList)}

proc addCorsHeaders(headers: var HttpHeaders) =
  headers["Access-Control-Allow-Origin"] = "*"
  headers["Access-Control-Allow-Methods"] = "GET, POST, OPTIONS"
  headers["Access-Control-Allow-Headers"] = "Content-Type, Authorization"

proc handleRequest(req: Request) {.async.} =
  var headers = newHttpHeaders()
  addCorsHeaders(headers)

  if req.reqMethod == HttpOptions:
    await req.respond(Http200, "", headers)
    return

  if req.url.path == "/" and req.reqMethod == HttpGet:
    try:
      let htmlContent = readFile("index.html")
      headers["Content-Type"] = "text/html; charset=utf-8"
      await req.respond(Http200, htmlContent, headers)
    except IOError:
      await req.respond(Http404, "index.html nem található", headers)
    return

  if req.url.path == "/chat" and req.reqMethod == HttpPost:
    try:
      let body = parseJson(req.body)
      let messages = body["messages"]
      let response = await callCerebras(messages)
      headers["Content-Type"] = "application/json; charset=utf-8"
      await req.respond(Http200, $(%*{"response": response}), headers)
    except Exception as e:
      await req.respond(Http500, $(%*{"error": e.msg}), headers)
    return

  if req.url.path == "/deepsearch" and req.reqMethod == HttpPost:
    try:
      let body = parseJson(req.body)
      let query = body["query"].getStr()
      let result = await performDeepResearch(query)
      headers["Content-Type"] = "application/json; charset=utf-8"
      await req.respond(Http200, $result, headers)
    except Exception as e:
      await req.respond(Http500, $(%*{"error": e.msg}), headers)
    return

  await req.respond(Http404, "Not Found", headers)

proc startServer() {.async.} =
  echo "JADED AI Kutatási Asszisztens"
  echo "Szerver indul: "
  let cerebrasStatus = if getEnv("CEREBRAS_API_KEY").len > 0: "OK" else "HIÁNYZIK"
  let exaStatus = if getEnv("EXA_API_KEY").len > 0: "OK" else "HIÁNYZIK"
  echo fmt"Cerebras API kulcs: {cerebrasStatus}"
  echo fmt"Exa API kulcs: {exaStatus}"
  await server.serve(Port(5000), handleRequest, "0.0.0.0")

when isMainModule:
  waitFor startServer()
```

