            scrollToBottom();
        }

        function hideTypingIndicator() {
            AppState.isTyping = false;
            const indicator = getEl('typingIndicator');
            if (indicator) indicator.remove();
            if(progressInterval) clearInterval(progressInterval);
        }

        function showResearchProgress() {
            hideTypingIndicator();
            const div = document.createElement('div');
            div.id = 'researchProgress';
            div.className = 'message ai-message';
            div.innerHTML = `
                <div class="ai-content research-progress-card">
                    <div class="spinner"></div>
                    <div class="phase-text" id="phaseText">Kutatás indítása...</div>
                    <div class="phase-subtitle">Ez több percig is eltarthat</div>
