                phaseIndex = (phaseIndex + 1) % phases.length;
                getEl('phaseText').textContent = phases[phaseIndex];
            }, 8000);
        }

        function hideResearchProgress() {
            clearInterval(progressInterval);
            const progress = getEl('researchProgress');
            if (progress) progress.remove();
        }

        async function sendMessage() {
            const message = messageInput.value.trim();
            if (!message) return;
            addUserMessage(message);
            messageInput.value = '';
            messageInput.dispatchEvent(new Event('input'));

            if (AppState.isDeepSearchActive) {
                await startResearch(message);
            } else {
                await sendChat(message);
            }
        }

        async function sendChat(message) {
            showTypingIndicator();
            try {
                const response = await fetch('/chat', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ messages: messageHistory.slice(-10) })
                });
                const data = await response.json();
                hideTypingIndicator();
                addAiMessage(data.response || "Hiba történt.");
            } catch (error) {
                hideTypingIndicator();
                addAiMessage("Kommunikációs hiba. Próbáld újra később.");
