        async function startResearch(query) {
            showResearchProgress();
            AppState.currentQuery = query;
            try {
                const response = await fetch('/deepsearch', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ query })
                });
                const data = await response.json();
                hideResearchProgress();
                if (data.report && data.sources) {
                    AppState.currentReport = data.report;
                    AppState.currentSources = data.sources;
                    const summary = data.report.split('\n').slice(0, 5).join('\n') + "\n\n**A teljes jelentés megtekintéséhez kattints ide.**";
                    addAiMessage(summary, true, query);
                } else {
                    addAiMessage(data.error || "Ismeretlen hiba a kutatás során.");
                }
            } catch (error) {
                hideResearchProgress();
                addAiMessage("Hálózati hiba a kutatás során. Próbáld újra.");
            }
        }

        function openViewer() {
            viewerTitle.textContent = `Kutatási jelentés: ${AppState.currentQuery}`;
            let sourceHTML = '<h2>Források</h2><ul>';
            AppState.currentSources.forEach(source => {
                sourceHTML += `<li>${escapeHtml(source.title)}</li>`;
