            sourceHTML += '</ul>';
            viewerContent.innerHTML = marked.parse(AppState.currentReport) + sourceHTML;
            documentViewer.style.display = 'flex';
        }

        function closeViewer() {
            documentViewer.style.display = 'none';
        }

        function downloadReport() {
            const content = `# Kutatási jelentés: ${AppState.currentQuery}\n\n${AppState.currentReport}\n\n## Források\n${AppState.currentSources.map(s => `- [${s.title}](${s.url})`).join('\n')}`;
            const blob = new Blob([content], { type: 'text/markdown;charset=utf-8' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `kutatasi-jelentes-${AppState.currentQuery.replace(/\s+/g, '-')}.md`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        }

        async function shareReport() {
            const shareData = {
                title: `Kutatási jelentés: ${AppState.currentQuery}`,
                text: AppState.currentReport.substring(0, 300) + "...",
            };
            try {
                if (navigator.share) {
                    await navigator.share(shareData);
                } else {
                   navigator.clipboard.writeText(AppState.currentReport);
                   alert("A jelentés a vágólapra másolva.");
                }
            } catch (err) {
                console.error("Megosztási hiba:", err);
            }
        }

        function setupEventListeners() {
            messageInput.addEventListener('input', () => {
                sendBtn.classList.toggle('active', messageInput.value.trim().length > 0);
                messageInput.style.height = 'auto';
                messageInput.style.height = Math.min(messageInput.scrollHeight, 140) + 'px';
            });
            messageInput.addEventListener('keydown', e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendMessage(); } });
            sidebarOverlay.addEventListener('click', closeSidebar);

            let touchstartX = 0;
            mainContent.addEventListener('touchstart', e => { touchstartX = e.changedTouches[0].screenX; }, {passive: true});
            mainContent.addEventListener('touchend', e => {
                if (touchstartX < 50 && e.changedTouches[0].screenX > touchstartX + 60) {
                    toggleSidebar();
                }
            });
        }

        document.addEventListener('DOMContentLoaded', () => {
