            setupEventListeners();
            messageInput.focus();
            setTimeout(() => {
                newChat();
                const blobs = document.querySelectorAll('.aurora-background .aurora');
                blobs.forEach(b => b.classList.add('visible'));
            }, 500);
        });

    </script>
