import net, strutils, json, os, asyncdispatch, asynchttpserver, asyncnet, httpclient, uri, strformat, tables, times, random

var server = newAsyncHttpServer()

const CEREBRAS_API_KEY_DEFAULT = "csk-6k3jvehx4dr8524856ck5j32erjtjet86dxpy9fyd9nwedft"
const EXA_API_KEY_DEFAULT = "d3587a67-95ba-4201-8b4c-a70cb04307fb"

proc envOrDefault(k, v: string): string =
  let e = getEnv(k)
  (if e.len > 0: e else: v)

proc bearer(h: var HttpHeaders; token: string) =
  h["Authorization"] = "Bearer " & token
  h["Content-Type"] = "application/json"

proc callCerebras(messages: JsonNode; maxTokens: int = 65000; temperature = 0.09; topP = 0.05): Future[string] {.async.} =
  let client = newAsyncHttpClient()
  try:
    var headers = newHttpHeaders()
    headers.bearer(envOrDefault("CEREBRAS_API_KEY", CEREBRAS_API_KEY_DEFAULT))
    client.headers = headers
    let bodyJson = %*{
      "model": "gpt-oss-120b",
      "messages": messages,
      "stream": false,
      "max_completion_tokens": maxTokens,
      "temperature": temperature,
      "top_p": topP
    }
    let response = await client.postContent("", $bodyJson)
    let jsonResponse = parseJson(response)
    if jsonResponse.hasKey("choices") and jsonResponse["choices"].len > 0:
      return jsonResponse["choices"][0]["message"]["content"].getStr()
    return "Hiba: Üres válasz a Cerebras API-tól."
  except Exception as e:
    return "Cerebras API hiba: " & e.msg
  finally:
    client.close()

proc exaSearchRaw(body: JsonNode): Future[JsonNode] {.async.} =
  let client = newAsyncHttpClient()
  try:
    var headers = newHttpHeaders()
    headers.bearer(envOrDefault("EXA_API_KEY", EXA_API_KEY_DEFAULT))
    client.headers = headers
    let resp = await client.postContent("", $body)
    return parseJson(resp)
  except Exception as e:
    return %*{"error": e.msg}
  finally:
    client.close()

proc exaQuery(query: string; typ = "fast"; numResults = 100; includeText = true; textLength = 200000; useAutoprompt = true): Future[JsonNode] {.async.} =
  var body = %*{
    "query": query,
    "numResults": numResults,
    "includeText": includeText,
    "textLength": textLength,
    "type": typ
  }
  if useAutoprompt: body["useAutoprompt"] = %*true
  return await exaSearchRaw(body)

proc exaSearchWithFallback(query: string): Future[JsonNode] {.async.} =
  let types = @["neural", "keyword", "fast"]
  for t in types:
    let res = await exaQuery(query, typ = t, numResults = 100, includeText = true, textLength = 200000, useAutoprompt = true)
    if res.hasKey("results") and res["results"].kind == JArray and res["results"].len > 0:
      return res
  return %*{"results": []}

proc nowSec(): int64 = int64(epochTime())

type JobProgress = object
  phase: string
  iteration: int
  totalIterations: int
  foundCount: int
  startTs: int64
  elapsedSec: int
  etaSec: int
  status: string

var jobProgress*: Table[string, JobProgress]
var jobReport*: Table[string, JsonNode]

proc setProgress(jobId, phase: string; iteration, totalIterations, foundCount: int; startTs: int64; timeLimitSec: int) =
  let elapsed = int(epochTime()) - int(startTs)
  let eta = max(0, timeLimitSec - elapsed)
  jobProgress[jobId] = JobProgress(
    phase: phase,
    iteration: iteration,
    totalIterations: totalIterations,
    foundCount: foundCount,
    startTs: startTs,
    elapsedSec: elapsed,
    etaSec: eta,
    status: (if iteration >= totalIterations and phase == "Kész": "completed" else: "running")
  )

proc buildResearchMessages(userQuery: string; researchData: string; sources: seq[string]): JsonNode =
  %*[
    {
      "role": "system",
      "content": "Te világszínvonalú kutatási szakértő vagy. Készíts rendkívül részletes, tudományos igényű jelentést magyarul, pontos hivatkozásokkal, strukturált fejezetekkel és összefoglalóval."
    },
    {
      "role": "user",
      "content": fmt"""
Téma: {userQuery}

Kutatási anyagok:
{researchData}

Forráslista ({sources.len} db):
{sources.join("\n")}
"""
    }
  ]

proc performDeepResearchIter(jobId, userQuery: string; timeLimitSec = 1800) {.async.} =
  let startTs = nowSec()
  var sources: Table[string, JsonNode]
  var researchData = newStringOfCap(512_000)
  var foundTotal = 0
  var iteration = 0
  let totalIterations = 6

  setProgress(jobId, "Kezdeti keresés (Exa)", iteration, totalIterations, foundTotal, startTs, timeLimitSec)
  let initial = await exaSearchWithFallback(userQuery)
  if initial.hasKey("results") and initial["results"].kind == JArray:
    for it in initial["results"]:
      let url = it.getOrDefault("url").getStr("")
      if url.len > 0 and (not sources.hasKey(url)):
        sources[url] = it
  foundTotal = sources.len
  iteration = 1
  setProgress(jobId, "Kezdeti keresés kész", iteration, totalIterations, foundTotal, startTs, timeLimitSec)

  let plannerMessages = %*[
    {"role":"system","content":"You are a research query planner. Given a topic, produce a JSON array of 8 highly specific Hungarian queries to uncover missing aspects, data, controversies, and latest developments. Only output JSON array of strings."},
    {"role":"user","content": userQuery}
  ]
  setProgress(jobId, "Lekérdezés-tervezés (Cerebras)", iteration, totalIterations, foundTotal, startTs, timeLimitSec)
  let planRaw = await callCerebras(plannerMessages, maxTokens = 800)
  var planned: seq[string] = @[]
  try:
    let arr = parseJson(planRaw)
    if arr.kind == JArray:
      for q in arr: planned.add(q.getStr())
  except JsonParsingError:
    discard
  if planned.len == 0:
    planned = @[
      userQuery & " legfrissebb hírek és fejlemények",
      userQuery & " statisztikák és adatok 2024-2025",
      userQuery & " tudományos publikációk áttekintés",
      userQuery & " szakértői vélemények és viták",
      userQuery & " nemzetközi összehasonlítás",
      userQuery & " esettanulmányok példák",
      userQuery & " kockázatok lehetőségek",
      userQuery & " trendek előrejelzések"
    ]
  iteration = 2
  setProgress(jobId, "Bővített keresések (Exa)", iteration, totalIterations, foundTotal, startTs, timeLimitSec)

  for i, q in planned:
    if int(epochTime()) - int(startTs) > timeLimitSec: break
    let res = await exaSearchWithFallback(q)
    if res.hasKey("results") and res["results"].kind == JArray:
      for it in res["results"]:
        let url = it.getOrDefault("url").getStr("")
        if url.len > 0 and (not sources.hasKey(url)):
          sources[url] = it
    foundTotal = sources.len
    setProgress(jobId, fmt"Bővített keresések ({i+1}/{planned.len})", iteration, totalIterations, foundTotal, startTs, timeLimitSec)

  iteration = 3
  setProgress(jobId, "Hiányok feltárása (Cerebras)", iteration, totalIterations, foundTotal, startTs, timeLimitSec)
  let gapMessages = %*[
    {"role":"system","content":"You are a research critic. Output a JSON array of 6 missing subtopics or blind spots for deeper search (in Hungarian). Only the JSON array."},
    {"role":"user","content": userQuery}
  ]
  let gapRaw = await callCerebras(gapMessages, maxTokens = 600)
  var gaps: seq[string] = @[]
  try:
    let arr = parseJson(gapRaw)
    if arr.kind == JArray:
      for v in arr: gaps.add(v.getStr())
  except JsonParsingError:
    discard
  if gaps.len > 0:
    for i, g in gaps:
      if int(epochTime()) - int(startTs) > timeLimitSec: break
      let res = await exaSearchWithFallback(g)
      if res.hasKey("results") and res["results"].kind == JArray:
        for it in res["results"]:
          let url = it.getOrDefault("url").getStr("")
          if url.len > 0 and (not sources.hasKey(url)):
            sources[url] = it
      foundTotal = sources.len
      setProgress(jobId, fmt"Hiányok keresése ({i+1}/{gaps.len})", iteration, totalIterations, foundTotal, startTs, timeLimitSec)

  iteration = 4
  setProgress(jobId, "Források összerendezése", iteration, totalIterations, foundTotal, startTs, timeLimitSec)
  var srcSeq: seq[(string, JsonNode)]
  for url, node in sources: srcSeq.add((url, node))
  srcSeq.sort(proc(a, b: (string, JsonNode)): int =
    let sa = a[1].getOrDefault("score").getFloat(0.0)
    let sb = b[1].getOrDefault("score").getFloat(0.0)
    if sa < sb: 1 elif sa > sb: -1 else: 0
  )
  let maxKeep = min(300, srcSeq.len)
  var kept = srcSeq[0 ..< maxKeep]

  var srcList: seq[string] = @[]
  for i, (url, node) in kept:
    let title = node.getOrDefault("title").getStr("Nincs cím")
    let text = node.getOrDefault("text").getStr("")
    researchData.add(fmt"## Forrás {i+1}: {title}\nURL: {url}\n\n{text}\n\n---\n")
    srcList.add(url)
  foundTotal = kept.len
  setProgress(jobId, "Elemzés és jelentéskészítés (Cerebras)", iteration, totalIterations, foundTotal, startTs, timeLimitSec)

  iteration = 5
  let analysis = buildResearchMessages(userQuery, researchData, srcList)
  let report = await callCerebras(analysis, maxTokens = 65000, temperature = 0.1, topP = 0.9)
  iteration = 6
  setProgress(jobId, "Kész", iteration, totalIterations, foundTotal, startTs, timeLimitSec)

  var sourceList: seq[JsonNode]
  for (url, node) in kept:
    sourceList.add(%*{"title": node.getOrDefault("title").getStr("N/A"), "url": url})

  jobReport[jobId] = %*{
    "report": report,
    "sources": sourceList,
    "query": userQuery,
    "wordCount": report.split(" ").len
  }

proc addCorsHeaders(headers: var HttpHeaders) =
  headers["Access-Control-Allow-Origin"] = "*"
  headers["Access-Control-Allow-Methods"] = "GET, POST, OPTIONS"
  headers["Access-Control-Allow-Headers"] = "Content-Type, Authorization"
  headers["Cache-Control"] = "no-cache"

proc handleRequest(req: Request) {.async.} =
  var headers = newHttpHeaders()
  addCorsHeaders(headers)

  if req.reqMethod == HttpOptions:
    await req.respond(Http200, "", headers)
    return

  if req.url.path == "/" and req.reqMethod == HttpGet:
    try:
      let htmlContent = readFile("index.html")
      headers["Content-Type"] = "text/html; charset=utf-8"
      await req.respond(Http200, htmlContent, headers)
    except IOError:
      await req.respond(Http404, "index.html nem található", headers)
    return

  if req.url.path == "/chat" and req.reqMethod == HttpPost:
    try:
      let body = parseJson(req.body)
      let messages = body.getOrDefault("messages")
      let response = await callCerebras(messages)
      headers["Content-Type"] = "application/json; charset=utf-8"
      await req.respond(Http200, $(%*{"response": response, "timestamp": $now(), "status":"success"}), headers)
    except Exception as e:
      await req.respond(Http500, $(%*{"error": e.msg}), headers)
    return

  if req.url.path == "/deepsearch" and req.reqMethod == HttpPost:
    try:
      let body = parseJson(req.body)
      let query = body.getOrDefault("query").getStr("")
      if query.len == 0:
        await req.respond(Http400, $(%*{"error":"Üres kutatási téma"}), headers)
        return
      let reportJson = block:
        let initial = await exaSearchWithFallback(query)
        var sources: seq[string] = @[]
        var researchData = ""
        if initial.hasKey("results") and initial["results"].kind == JArray:
          var i = 0
          for it in initial["results"]:
            if i >= 100: break
            let url = it.getOrDefault("url").getStr("")
            if url.len > 0:
              sources.add(url)
              let title = it.getOrDefault("title").getStr("Nincs cím")
              let text = it.getOrDefault("text").getStr("")
              researchData.add(fmt"## Forrás {i+1}: {title}\nURL: {url}\n\n{text}\n\n---\n")
              inc i
        let analysis = buildResearchMessages(query, researchData, sources)
        let report = await callCerebras(analysis, maxTokens = 65000, temperature = 0.1, topP = 0.9)
        %*{"report": report, "sources": (for s in sources: %*{"title":"Forrás", "url": s}).toJson
      headers["Content-Type"] = "application/json; charset=utf-8"
      await req.respond(Http200, $reportJson, headers)
    except Exception as e:
      await req.respond(Http500, $(%*{"error": e.msg}), headers)
    return

  if req.url.path == "/deepsearch/start" and req.reqMethod == HttpPost:
    try:
      let body = parseJson(req.body)
      let query = body.getOrDefault("query").getStr("")
      var timeLimitSec = body.getOrDefault("timeLimitSec").getInt(1800)
      if timeLimitSec < 60: timeLimitSec = 60
      if query.len == 0:
        await req.respond(Http400, $(%*{"error":"Üres kutatási téma"}), headers)
        return
      randomize()
      let jobId = "job_" & $(rand(10_000_000 .. 99_999_999))
      jobProgress[jobId] = JobProgress(phase: "Indítás", iteration: 0, totalIterations: 6, foundCount: 0, startTs: nowSec(), elapsedSec: 0, etaSec: timeLimitSec, status: "running")
      asyncCheck performDeepResearchIter(jobId, query, timeLimitSec)
      headers["Content-Type"] = "application/json; charset=utf-8"
      await req.respond(Http200, $(%*{"jobId": jobId, "status":"started"}), headers)
    except Exception as e:
      await req.respond(Http500, $(%*{"error": e.msg}), headers)
    return

  if req.url.path == "/deepsearch/progress" and req.reqMethod == HttpGet:
    let qp = req.url.query
    var jobId = ""
    if "id=" in qp:
      jobId = qp.split("id=")[1]
    if jobId.len == 0 or (jobId notin jobProgress):
      await req.respond(Http404, $(%*{"error":"Ismeretlen jobId"}), headers)
      return
    let p = jobProgress[jobId]
    let payload = %*{
      "jobId": jobId,
      "phase": p.phase,
      "iteration": p.iteration,
      "totalIterations": p.totalIterations,
      "foundCount": p.foundCount,
      "elapsedSec": p.elapsedSec,
      "etaSec": p.etaSec,
      "status": p.status
    }
    headers["Content-Type"] = "application/json; charset=utf-8"
    await req.respond(Http200, $payload, headers)
    return

  if req.url.path == "/deepsearch/result" and req.reqMethod == HttpGet:
    let qp = req.url.query
    var jobId = ""
    if "id=" in qp:
      jobId = qp.split("id=")[1]
    if jobId.len == 0 or (jobId notin jobReport):
      await req.respond(Http404, $(%*{"error":"Eredmény nem található"}), headers)
      return
    headers["Content-Type"] = "application/json; charset=utf-8"
    await req.respond(Http200, $jobReport[jobId], headers)
    return

  headers["Content-Type"] = "application/json; charset=utf-8"
  await req.respond(Http404, $(%*{"error":"Endpoint nem található","path":req.url.path}), headers)

proc startServer() {.async.} =
  await server.serve(Port(5000), handleRequest, "0.0.0.0")

when isMainModule:
  waitFor startServer()
